import math
    import random
    import time

    LANGUAGE_WRAPPER = 'On the integer lattice, an object starts at (0,0) and may take up to {total_steps} unit steps. At each step it moves right, left, up, or down with probabilities proportional to {w_right}, {w_left}, {w_up}, and {w_down}, respectively (that is, the probabilities are {w_right}/W, {w_left}/W, {w_up}/W, and {w_down}/W where W={w_right}+{w_left}+{w_up}+{w_down}). The object is forbidden from visiting any point with y < -{barrier_depth}. Let p be the probability that the object first reaches either of the two target points ({t1_x}, {t1_y}) or ({t2_x}, {t2_y}) within at most {total_steps} steps without ever entering the forbidden half-plane y < -{barrier_depth}. Write p as m/n in lowest terms and find m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Random but controlled generation for a challenging instance.
# Ensures anisotropic step probabilities, two targets, and a nontrivial half-plane avoidance.
while True:
    T = rng.randint(10, 14)
    # Choose step weights from 1..3, ensure not all equal to keep anisotropy
    w = [rng.randint(1, 3) for _ in range(4)]
    if len(set(w)) < 2:
        continue
    w_right, w_left, w_up, w_down = w
    barrier_depth = rng.randint(1, 3)
    # Choose target coordinates positive/zero y to avoid trivial blocking by barrier.
    # Keep them moderately small but ensure reachability and diversity.
    def pick_target():
        x = rng.randint(1, min(6, T - 2))
        y = rng.randint(0, min(6, T - 2))
        return x, y
    t1_x, t1_y = pick_target()
    while True:
        t2_x, t2_y = pick_target()
        if (t2_x, t2_y) != (t1_x, t1_y):
            break
    # Ensure minimal Manhattan distance is at least 2 less than T to avoid trivial tight cases.
    d1 = abs(t1_x) + abs(t1_y)
    d2 = abs(t2_x) + abs(t2_y)
    dmin = min(d1, d2)
    if dmin > T:
        continue
    if T - dmin < 2:
        continue
    # Ensure barrier does not invalidate start or targets
    if 0 < -barrier_depth:
        continue
    if t1_y < -barrier_depth or t2_y < -barrier_depth:
        continue
    return {
        'total_steps': T,
        'w_right': w_right,
        'w_left': w_left,
        'w_up': w_up,
        'w_down': w_down,
        'barrier_depth': barrier_depth,
        't1_x': t1_x,
        't1_y': t1_y,
        't2_x': t2_x,
        't2_y': t2_y
    }

    def verifier(assign):
# Validate domain and compute exact probability using an absorbing DP with rational arithmetic.
# Returns (True, answer) on success; otherwise (False, None).
from fractions import Fraction
# Basic key presence
keys = ['total_steps', 'w_right', 'w_left', 'w_up', 'w_down', 'barrier_depth', 't1_x', 't1_y', 't2_x', 't2_y']
for k in keys:
    if k not in assign:
        # Missing parameters
        return (False, None)
# Extract and validate types
try:
    T = int(assign['total_steps'])
    wr = int(assign['w_right'])
    wl = int(assign['w_left'])
    wu = int(assign['w_up'])
    wd = int(assign['w_down'])
    b = int(assign['barrier_depth'])
    x1 = int(assign['t1_x'])
    y1 = int(assign['t1_y'])
    x2 = int(assign['t2_x'])
    y2 = int(assign['t2_y'])
except Exception:
    # Non-integer values
    return (False, None)
# Domain constraints and difficulty enforcement
if not (10 <= T <= 20):
    # Keep steps moderately large for difficulty but bounded for runtime
    return (False, None)
for w in (wr, wl, wu, wd):
    if w <= 0:
        return (False, None)
if len(set([wr, wl, wu, wd])) < 2:
    # Require anisotropy to prevent trivial uniform cases
    return (False, None)
if b <= 0:
    return (False, None)
# Start and targets cannot be in forbidden region
if 0 < -b:
    return (False, None)
if y1 < -b or y2 < -b:
    return (False, None)
# Distinct targets; not at origin
if (x1, y1) == (0, 0) or (x2, y2) == (0, 0):
    return (False, None)
if (x1, y1) == (x2, y2):
    return (False, None)
# Basic reachability by Manhattan distance
d1 = abs(x1) + abs(y1)
d2 = abs(x2) + abs(y2)
dmin = min(d1, d2)
if dmin > T:
    return (False, None)
if T - dmin < 2:
    # Ensure union-over-time nature; avoids trivial tight equality
    return (False, None)
# Construct exact probabilities
W = wr + wl + wu + wd
pR = Fraction(wr, W)
pL = Fraction(wl, W)
pU = Fraction(wu, W)
pD = Fraction(wd, W)
# Absorbing DP: dist_t(pos) stores probability of being at pos after t steps having never hit targets nor the forbidden half-plane.
dist = {(0, 0): Fraction(1, 1)}
success = Fraction(0, 1)
target1 = (x1, y1)
target2 = (x2, y2)
# Forbidden predicate
def forbidden(pt):
    return pt[1] < -b
# Transition deltas
moves = [((1, 0), pR), ((-1, 0), pL), ((0, 1), pU), ((0, -1), pD)]
for _ in range(T):
    next_dist = {}
    for (x, y), pr in dist.items():
        if pr == 0:
            continue
        for (dx, dy), pm in moves:
            nx, ny = x + dx, y + dy
            contrib = pr * pm
            if forbidden((nx, ny)):
                # Absorb into failure; do nothing
                continue
            if (nx, ny) == target1 or (nx, ny) == target2:
                # First hit accumulated into success; do not propagate further
                success += contrib
            else:
                key = (nx, ny)
                prev = next_dist.get(key, Fraction(0, 1))
                next_dist[key] = prev + contrib
    dist = next_dist
# Ensure nontriviality: probability neither 0 nor 1
if success == 0 or success == 1:
    return (False, None)
# Final answer m+n
m = success.numerator
n = success.denominator
answer = m + n
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

